INSERT INTO `leads` (`id`, `name`, `phone`, `email`, `caseType`, `caseNumber`, `source`, `stage`, `notes`, `date`, `retainerBooked`, `downpayment`, `quotedAmount`, `referredBy`, `convertedDate`, `createdAt`, `updatedAt`, `lostReason`, `consultationFee`, `followUpDate`, `assignedTo`) VALUES ('97APXSl9qwIELiMNuhSOb', 'Navneet', '+1 (209) 327-9341', '', 'AOS', '', 'Existing client', 'Follow-Up', 'The husband is a green card holder and the wife is a Canadian citizen. They filed the I-130 last year, received the F2A notice, waited 90 days, and then filed Adjustment of Status. After a fight, the husband sent a withdrawal request for the I-130, and USCIS received it about a month ago. Now they both want to continue the case.\n\nThey don’t have online access to the I-130, and the wife’s visa expired 6 months ago, so she is very worried.\n\nCan a withdrawn I-130 be continued, or does he need to file a new one? \nInformed her about the consultation fee\nClient still arranging funds. will follow up next week.\n', '2026-06-01', '0.00', '0.00', '0.00', ' malkeet kaur sijs', NULL, '2026-06-01 17:59:09.000', '2026-06-08 21:58:16.000', NULL, '150.00', '2026-06-09', NULL);
