INSERT INTO `leads` (`id`, `name`, `phone`, `email`, `caseType`, `caseNumber`, `source`, `stage`, `notes`, `date`, `retainerBooked`, `downpayment`, `quotedAmount`, `referredBy`, `convertedDate`, `createdAt`, `updatedAt`, `lostReason`, `consultationFee`, `followUpDate`, `assignedTo`) VALUES ('cQwfaiTVuBY2N1PJRji8F', 'Abdul Adam', '+1916-289-6843 ', '', 'Green Card', '', 'Google', 'Follow-Up', 'Abdul Adam reached out regarding his relative’s green card. The relative, Mohamed Essa Abdi, lost his green card a few years ago but is still residing in the U.S. I informed the client about the consultation fee but he is asking for an estimate of the total charges for the green card process.\n\n1. Card Status\nIs your Green Card:\n☐ Lost\n☐ Stolen\n☐ Expired\n☐ Damaged\n2. Card Type (THIS DECIDES EVERYTHING)\nWas your Green Card valid for:\n☐ 10 years (regular)\n☐ 2 years (conditional – through marriage/investment)\n3. Expiration Timing\nIf expired:\nWhen did it expire? (MM/YYYY)\n4. Time Outside the U.S. (CRITICAL RISK CHECK)\nHave you stayed outside the U.S. for:\n☐ More than 6 months continuously?\n☐ More than 1 year continuously?\n5. Current Location\nAre you currently:\n☐ Inside the U.S.\n☐ Outside the U.S.\n6. Proof Available\nDo you have any of the following:\n☐ Copy/photo of Green Card\n☐ A-Number\n☐ Passport\n7. Urgency\nDo you need proof urgently for:\n☐ Work\n☐ Travel\n☐ Driver’s license\n\nClient will confirm and let us know in a 1-2 days, will follow up on 04/23/2026\n04/23/2026 K: Client will discuss with his relative and get back to us on his own, will follow up on Monday\n04/27/2026 K: client will let us know on his own, will follow up on 04/30/2026\n04/30/2026K: His relative sister will visit him August, he\'ll get back to us in August', '2026-04-22', '0.00', '0.00', '0.00', 'Google generated', NULL, '2026-06-01 18:17:56.000', '2026-06-01 21:25:13.000', NULL, '150.00', '2026-08-03', NULL);
INSERT INTO `leads` (`id`, `name`, `phone`, `email`, `caseType`, `caseNumber`, `source`, `stage`, `notes`, `date`, `retainerBooked`, `downpayment`, `quotedAmount`, `referredBy`, `convertedDate`, `createdAt`, `updatedAt`, `lostReason`, `consultationFee`, `followUpDate`, `assignedTo`) VALUES ('D_GyHTBybRYB7-zGONgCH', 'Tajinder Singh', '+1 (559) 801-2384', '', 'DA', '274', 'Tajinder', 'New Lead', 'He is already our client for I-130, now his merit is coming he wants to purse his DA case with us since processing time is saying that he can file inquiry by 2033.', '2026-06-03', '0.00', '0.00', '8000.00', 'He is already our client', NULL, '2026-06-04 04:12:09.000', '2026-06-08 21:46:08.000', NULL, '150.00', '2026-06-10', NULL);
