INSERT INTO `lead_notes` (`id`, `leadId`, `text`, `timestamp`, `createdAt`, `authorName`) VALUES ('1eZJtVci-j_wAAoEJRJAB', 'GaibNN5qq0p1x9cwlgG9f', 'Client is our previous client and currently has a pending asylum case with our office. Client reports that on the night of May 31, 2026, he was attacked by four unknown individuals at a friend\'s house. He sustained a head injury requiring three stitches and was treated at San Joaquin General Hospital. Medical records document assault-related injuries, including a head laceration, closed head injury, and loss of consciousness (LOC). Photographs of the injuries are available.  Client filed a police report (Report No. 26-02562). Detectives are actively investigating the incident and have reportedly collected statements from other victims/witnesses. Client also received a Marsy\'s Card from the San Joaquin County District Attorney\'s Office.  Police report is expected next week. Once received, client will schedule an attorney consultation ($150) for further evaluation of potential U-Visa eligibility and law enforcement certification prospects while considering the impact on his pending asylum case.', '2026-06-02T17:33:24.306Z', '2026-06-02 21:33:24.000', 'Sachin');
INSERT INTO `lead_notes` (`id`, `leadId`, `text`, `timestamp`, `createdAt`, `authorName`) VALUES ('24IESpbRXVIOyg6Q59egQ', '5luMdYbvZwtCMmtH_sdDv', 'Consultation is done C will get back to us after she got married and also she has her declaration ready so SYLVA can see what case is about  Case from Venezuela  Please add notes and move lead into follw up', '2026-05-20T21:28:09.440Z', '2026-05-21 01:28:09.000', 'Sachin');
INSERT INTO `lead_notes` (`id`, `leadId`, `text`, `timestamp`, `createdAt`, `authorName`) VALUES ('2khSITgQgA_Wcqx-wCj-z', 'SKxHtLKyTu80J8xxa4g6l', 'Confirmed from attorney and attorney suggested boking consultation for 30 Mins on 16 june. Called lead on ring central to confirm. didnt pick up the call. No whatsapp being used by old lady. will have to call back again today/\n__DONE__:Khushi Arora:Jun 5, 2026 at 9:37 AM', '2026-06-05T16:37:00.958Z', '2026-06-05 20:37:00.000', 'Khushi Arora');
