INSERT INTO `lead_notes` (`id`, `leadId`, `text`, `timestamp`, `createdAt`, `authorName`) VALUES ('RhU_x8ho2VoXh2eiS3GIV', 'xaWqfnS6ZBTRCnChX0mBj', 'gave her details Step	What happens 1	Father files Form I-130 with USCIS. 2	USCIS issues receipt notice; this creates the priority date. 3	USCIS eventually approves the I-130. 4	Case goes to the National Visa Center. 5	The case waits until the F2B priority date becomes close/current. 6	NVC collects fees, DS-260, civil documents, police certificate, birth certificate, passport biographic page, and I-864 Affidavit of Support. 7	Daughter completes medical exam. 8	Interview is scheduled through the U.S. immigrant visa process in Canada, generally handled through Montreal. The U.S. Embassy in Canada lists the immigrant visa process as petition filing, NVC processing, interview appointment, medical exam, and consular interview. 9	If approved, she enters the U.S. as a permanent resident.', '2026-05-26T02:04:12.412Z', '2026-05-26 06:04:12.000', NULL);
INSERT INTO `lead_notes` (`id`, `leadId`, `text`, `timestamp`, `createdAt`, `authorName`) VALUES ('rMLe-tYM1ziopE0dDREig', 'qMG_lNSUr93-AFLf2PscW', 'No update from client yet, will follow up again after some time, will follow up on  on 06/17/2026\n__DONE__:Khushi Arora:Jun 8, 2026 at 11:12 AM', '2026-06-08T18:12:09.845Z', '2026-06-08 22:12:09.000', 'Khushi Arora');
