INSERT INTO `ai_lead_analysis` (`id`, `leadId`, `tier`, `score`, `headline`, `nextAction`, `riskFlags`, `reasoning`, `analyzedAt`, `createdAt`) VALUES ('0HRAirrttlKkicI_DhEBB', '97APXSl9qwIELiMNuhSOb', 'At-Risk', 10, 'Navneet - Consultation Payment Overdue, Multiple Reschedules', 'Immediate follow-up with client to confirm payment status and commitment, offer alternative payment options or consultation format.', '["Consultation payment repeatedly delayed","Client commitment seems low or uncertain","No service quoted yet, only consultation"]', 'Navneet is in the \'Follow-Up\' stage for 5 days, with no payment made for a consultation that was due on 06/05/2026. The client has repeatedly pushed back the payment date, indicating potential commitment issues or financial difficulties. The last update states payment by \'Monday\' (presumably 06/08/2026), but given the history, this is uncertain. No actual service has been quoted yet, only the consultation fee. This lead is at high risk of falling off if not addressed proactively.', '2026-06-07 12:02:36.000', '2026-06-07 12:02:36.000');
INSERT INTO `ai_lead_analysis` (`id`, `leadId`, `tier`, `score`, `headline`, `nextAction`, `riskFlags`, `reasoning`, `analyzedAt`, `createdAt`) VALUES ('3g5PmiA_L3IRhElGo9Qg8', 'lead-rajender-kumar-01', 'At-Risk', 10, 'Rajender Kumar: Client non-responsive after multiple follow-ups, at risk of disengagement.', 'Attempt a different communication channel or a final outreach with a clear deadline.', '["Non-responsive after multiple follow-ups","No payment received after 32 days","Follow-up date pushed back due to non-response"]', 'Rajender Kumar is in the \'Follow-Up\' stage for 32 days with no payment received on an $8000 quote. Multiple attempts to contact have been met with non-response, leading to the follow-up date being repeatedly pushed back. This indicates a high risk of disengagement.', '2026-06-07 12:03:39.000', '2026-06-07 12:03:39.000');
INSERT INTO `ai_lead_analysis` (`id`, `leadId`, `tier`, `score`, `headline`, `nextAction`, `riskFlags`, `reasoning`, `analyzedAt`, `createdAt`) VALUES ('4rephuVFbtHSUodhBoXT0', 'enxUgT1dCBp-yOmZADiK3', 'Warm', 10, 'Client uncertain about start date, requires re-engagement by next Friday.', 'Follow up with Akashdeep Singh on or before 2026-06-12 to confirm their decision on starting the DA process.', '["Client indecision on commitment","Potential for lead to go cold if not re-engaged promptly"]', 'Akashdeep Singh is currently in the \'Follow-Up\' stage for a DA case. While initial attempts to connect were difficult (client picking up but not speaking), a recent follow-up on 2026-06-05 revealed the client is \'not sure when he wants to start the process\' but promised to \'confirm by next week friday\'. This indicates some level of interest but also significant indecision. The lead is not \'Hot\' due to the uncertainty, but not \'Cold\' as there\'s a clear next step and a stated commitment to confirm. The \'Warm\' tier is appropriate, reflecting potential with a need for careful nurturing. The score of 50 reflects this moderate interest and the pending decision. The next action is to follow up as promised by the client.', '2026-06-07 12:03:33.000', '2026-06-07 12:03:33.000');
INSERT INTO `ai_lead_analysis` (`id`, `leadId`, `tier`, `score`, `headline`, `nextAction`, `riskFlags`, `reasoning`, `analyzedAt`, `createdAt`) VALUES ('5QEcnKel1txTxvvEBld1z', 'cQwfaiTVuBY2N1PJRji8F', 'At-Risk', 10, 'Abdul Adam: At-Risk Green Card Lead - No Quote, No Follow-ups, Long Delay', 'Immediately contact Abdul Adam to understand current status, re-engage interest, and provide initial consultation or quote.', '["No quote provided","No payment received","No follow-ups completed","Significant time elapsed since initial contact (45 days)","Future follow-up date is extremely far out (2026-08-03)"]', 'Abdul Adam is an \'At-Risk\' lead due to several critical factors. Despite being in the \'Follow-Up\' stage for a high-value \'Green Card\' case, no quote has been provided, and no payment has been received. Crucially, zero follow-ups have been completed over 45 days. The \'Next follow-up\' date of 2026-08-03 is a clear data entry error or indicates extreme neglect, making this lead highly likely to be lost without immediate intervention. The score of 30 reflects the high potential value of a Green Card case but is severely pulled down by the lack of engagement and significant risk factors.', '2026-06-07 12:01:57.000', '2026-06-07 12:01:57.000');
INSERT INTO `ai_lead_analysis` (`id`, `leadId`, `tier`, `score`, `headline`, `nextAction`, `riskFlags`, `reasoning`, `analyzedAt`, `createdAt`) VALUES ('6Lb7l81ptZAAWVVbGDr_l', 'D_GyHTBybRYB7-zGONgCH', 'Cold', 10, 'Tajinder Singh: Non-responsive, long-term follow-up, no payment.', 'Attempt follow-up on 2026-06-08 as scheduled. If still non-responsive, consider a final outreach before re-tiering to \'At-Risk\' or \'Cold - Archived\'.', '["Non-responsive","No payment received","Long gap until next follow-up"]', 'Tajinder Singh is a new lead for a DA case. While a quote was provided, there has been no payment. The client was non-responsive to the initial call, and the next follow-up is scheduled far in the future (2026-06-08), indicating a lack of immediate engagement or urgency from the client\'s side. This combination of non-responsiveness and delayed follow-up without any commitment places the lead in the \'Cold\' tier.', '2026-06-07 12:01:14.000', '2026-06-07 12:01:14.000');
INSERT INTO `ai_lead_analysis` (`id`, `leadId`, `tier`, `score`, `headline`, `nextAction`, `riskFlags`, `reasoning`, `analyzedAt`, `createdAt`) VALUES ('77YTmSdDAiNhpoiJNKXKr', '8eXxdH9S-tZKSjM0v3Kml', 'Warm', 10, 'Sarah Sahota: K1/K2 Lead - Active Follow-Up, No Contact Yet, Quote Pending', 'Attempt contact via alternative methods (email/text) if phone calls continue to be unanswered. Prepare a preliminary quote to send if contact is established.', '["No contact established after multiple attempts","No quote provided yet","Potential for lead to go cold if contact isn\'t made soon"]', 'Sarah Sahota is a K1/K2 lead in the follow-up stage for 5 days. There have been multiple attempts to contact her, all resulting in \'Call No Contact\' (CNC) messages left. No quote has been provided, and no payment has been received, which is expected given the lack of contact. The next follow-up is scheduled for 2026-06-08. The lead is \'Warm\' because there\'s an active interest (implied by the initial lead generation) and ongoing follow-up, but the lack of contact and pending quote prevent it from being \'Hot\'. The score reflects the active follow-up but also the challenge of establishing initial contact. The primary risk is that the lead will go cold if contact isn\'t made soon.', '2026-06-07 12:01:34.000', '2026-06-07 12:01:34.000');
INSERT INTO `ai_lead_analysis` (`id`, `leadId`, `tier`, `score`, `headline`, `nextAction`, `riskFlags`, `reasoning`, `analyzedAt`, `createdAt`) VALUES ('BqkNgn3OZq7prWe8hlZCI', 'JO_4iK9Yav79qervrcBqO', 'Cold', 10, 'Lead Henry Wang is Cold: Significant Follow-Up Overdue, No Quote, No Payment', 'Attempt immediate contact to assess interest and offer initial consultation. If no response, consider archiving.', '["Follow-up overdue by 18 days","No initial quote provided","No payment received","No completed follow-ups","Next follow-up scheduled far in the future (2026-06-08)"]', 'Henry Wang is classified as \'Cold\' due to multiple critical indicators: the lead is 18 days past its last follow-up with zero completed follow-ups, indicating a complete lack of recent engagement. No quote has been provided, and no payment has been received, suggesting the lead is very early stage or has lost interest. The \'Next follow-up\' date being set for 2026-06-08 is highly unusual and likely an error, further contributing to the \'Cold\' status, as it implies no immediate action is planned. The overall lack of activity and engagement points to a low probability of conversion without immediate intervention.', '2026-06-07 12:03:26.000', '2026-06-07 12:03:26.000');
INSERT INTO `ai_lead_analysis` (`id`, `leadId`, `tier`, `score`, `headline`, `nextAction`, `riskFlags`, `reasoning`, `analyzedAt`, `createdAt`) VALUES ('e9NyNHzguxbvazEFwwwmO', 'GaibNN5qq0p1x9cwlgG9f', 'Hot', 10, 'High-priority U-Visa lead: Existing asylum client with recent, well-documented assault and active police investigation. Requires immediate follow-up for attorney consultation.', 'Proactively contact client to confirm police report receipt and schedule attorney consultation. Prepare U-Visa eligibility assessment considering asylum case implications.', '["No payment received yet","Potential conflict/impact with existing asylum case"]', 'This lead is classified as \'Hot\' due to several critical factors: the client is an existing asylum client, indicating trust and established relationship; the incident is very recent (May 31, 2026); there is strong documentation of the assault including medical records, photographs, and an active police report (Report No. 26-02562). The client has also received a Marsy\'s Card, suggesting official recognition of victim status. The police report is expected next week, which is a clear trigger for the next step. The primary risk is the potential impact on the client\'s pending asylum case, which requires careful attorney evaluation. The $150 consultation fee is pending the police report, but the overall strength of the U-Visa claim makes this a high-priority lead for conversion.', '2026-06-07 12:01:41.000', '2026-06-07 12:01:41.000');
INSERT INTO `ai_lead_analysis` (`id`, `leadId`, `tier`, `score`, `headline`, `nextAction`, `riskFlags`, `reasoning`, `analyzedAt`, `createdAt`) VALUES ('fXd4i7DwRiNITPZsfo2l0', 'SKxHtLKyTu80J8xxa4g6l', 'At-Risk', 10, 'Noime Cruz: High risk of disengagement due to communication issues and lack of consultation booking.', 'Attempt immediate contact via phone (multiple times/numbers if available) to confirm consultation details. If no contact, consider alternative communication methods or closing the lead.', '["Communication difficulty (unresponsive to calls)","Consultation not yet booked despite attorney recommendation","No payment received","Lead is \'old lady\' - potential tech/communication barrier","Case type \'Other\' - potentially complex or undefined needs"]', 'Noime Cruz is a new lead with two completed follow-ups, but no successful contact has been made to schedule the attorney-recommended consultation. The lead has not picked up calls, and there\'s no WhatsApp contact. This indicates significant communication barriers, placing the lead at high risk of disengagement. Despite the attorney\'s interest, the inability to connect prevents progression. The \'Other\' case type also suggests potential ambiguity in needs. Urgent action is required to establish contact or the lead will likely be lost.', '2026-06-07 12:00:44.000', '2026-06-07 12:00:44.000');
INSERT INTO `ai_lead_analysis` (`id`, `leadId`, `tier`, `score`, `headline`, `nextAction`, `riskFlags`, `reasoning`, `analyzedAt`, `createdAt`) VALUES ('gCnD2mlMCZYl2SyyE38FK', 'Hrca7F8T4cwLHNv9iQPfF', 'At-Risk', 10, 'Rajender Kumar: Stalled Lead, Multiple CNCs, High Risk of Loss', 'Attempt immediate contact via alternative methods (email/text), or consider a final, urgent follow-up call. If no response, move to \'Lost\' after a defined period.', '["No payment received after 32 days","Multiple \'Call Not Connected\' (CNC) attempts","Lead unresponsive to repeated follow-ups","High quote value with no engagement","Next follow-up date is in the future (06/08/2026) despite current lack of contact"]', 'Rajender Kumar is a high-value lead ($8000 quote) but shows significant disengagement, having made no payment after 32 days. The CRM notes indicate multiple \'Call Not Connected\' attempts on June 2nd and 4th, with messages left. This pattern suggests the lead is either no longer interested, has found another solution, or is difficult to reach. The lack of any positive interaction despite repeated attempts places this lead in a high-risk category for being lost. An urgent intervention beyond standard follow-ups is required to prevent losing this potential client.', '2026-06-07 12:02:24.000', '2026-06-07 12:02:24.000');
INSERT INTO `ai_lead_analysis` (`id`, `leadId`, `tier`, `score`, `headline`, `nextAction`, `riskFlags`, `reasoning`, `analyzedAt`, `createdAt`) VALUES ('ggcMr2jC5LJz0KcNp2zyc', 'haN8EPo7Dnf3CmGrTRUcN', 'Warm', 10, 'Referred SIJS lead, but very long follow-up delay and no initial payment.', 'Review the reason for the extremely distant \'Next follow-up\' date (2026-06-15). If this is an error or a placeholder, update immediately. If intentional, document why. Consider an earlier, more direct outreach given the referral.', '["Very distant next follow-up date (2026-06-15)","No payment received","No completed follow-ups despite 18 days in stage"]', 'This lead is categorized as \'Warm\' primarily due to being a referral (Kay Khaing\'s nephew), which typically indicates a higher likelihood of conversion. However, several factors prevent it from being \'Hot\'. The \'Next follow-up\' date is an alarming 2026-06-15, suggesting either a significant error in data entry or a deliberate, but unexplained, long-term deferral. No payment has been received, and zero follow-ups have been completed in 18 days, which is concerning for an active lead. The SIJS case type can be complex and time-sensitive. The referral relationship warrants attention, but the lack of engagement and the bizarre follow-up date significantly reduce its immediate priority.', '2026-06-07 12:02:42.000', '2026-06-07 12:02:42.000');
INSERT INTO `ai_lead_analysis` (`id`, `leadId`, `tier`, `score`, `headline`, `nextAction`, `riskFlags`, `reasoning`, `analyzedAt`, `createdAt`) VALUES ('jza6LJVHOyLoPjH8jUDA9', '5luMdYbvZwtCMmtH_sdDv', 'Cold', 10, 'Isamary Perez Tovar: Long-term hold, awaiting marriage and declaration review.', 'Review case status and notes on 2026-07-27. Confirm if marriage occurred and declaration is ready for SYLVA\'s review.', '["Extended follow-up timeline (over 2 years)","Contingent on client actions (marriage, declaration)","No active engagement since initial consultation"]', 'Isamary has paid a small amount ($150) but the next follow-up is scheduled for over two years from now, indicating a very long-term hold based on future client actions (marriage and declaration readiness). This significantly reduces immediate priority. The \'Completed follow-ups: 0\' and \'Rescheduled: 0x\' suggest no active engagement since the initial consultation. The case is contingent on external factors, placing it in a \'Cold\' tier until those conditions are met and the client re-engages.', '2026-06-07 12:03:14.000', '2026-06-07 12:03:14.000');
INSERT INTO `ai_lead_analysis` (`id`, `leadId`, `tier`, `score`, `headline`, `nextAction`, `riskFlags`, `reasoning`, `analyzedAt`, `createdAt`) VALUES ('kt5bXazDq15v5M1I84zFa', 'CnEwQa-qk6I0rUo1MJe6-', 'Cold', 10, 'Soni: Low Engagement, Referral Pending, Multiple CNCs', 'Follow up as scheduled on 2026-06-08. If no response, consider re-evaluating lead status or archiving.', '["No direct contact established","Multiple \'Call Not Connected\' attempts","Reliance on third-party referral for progress","No quote provided yet"]', 'The lead \'Soni\' is currently assessed as \'Cold\'. Despite being a new lead (4 days), there has been no direct contact established. All attempts have resulted in \'Call Not Connected\' (CNC) with messages left. The only progress noted is a potential referral through \'Gursahib Singh\' who will speak to a friend, indicating the lead is not directly engaged. No quote has been provided, and no payment has been made. The repeated CNCs and reliance on a secondary party for follow-up suggest low immediate priority and engagement. The score reflects the newness of the lead but is tempered by the lack of direct contact and engagement issues.', '2026-06-07 12:01:27.000', '2026-06-07 12:01:27.000');
INSERT INTO `ai_lead_analysis` (`id`, `leadId`, `tier`, `score`, `headline`, `nextAction`, `riskFlags`, `reasoning`, `analyzedAt`, `createdAt`) VALUES ('Nbst72DDZBpbRSM5SoTVN', 'inDZcWfZtCVQvlVuhGVmy', 'At-Risk', 10, 'Rajesh Kumar: High-value lead, but currently stalled and at risk of loss due to delayed marriage plans.', 'Follow up on 2026-06-15 as scheduled, specifically inquiring about his marriage plans and re-engaging on the DA case. Offer alternative solutions if marriage is further delayed.', '["No payment received for a high quote","Client-initiated delay due to personal circumstances (marriage)","Client prefers to initiate contact, indicating potential disengagement","Long gap until next follow-up (over 10 days from current date)"]', 'Rajesh Kumar is a high-value lead with a $9000 quote, but has paid $0 and actively delayed the process due to not being married yet, stating he will initiate contact when ready. This puts the lead at significant risk of being lost or indefinitely postponed. The next follow-up is scheduled for 2026-06-15, which is a considerable wait given the current status. The \'At-Risk\' tier reflects the high quote value combined with the client-driven delay and lack of financial commitment.', '2026-06-07 12:02:13.000', '2026-06-07 12:02:13.000');
INSERT INTO `ai_lead_analysis` (`id`, `leadId`, `tier`, `score`, `headline`, `nextAction`, `riskFlags`, `reasoning`, `analyzedAt`, `createdAt`) VALUES ('NfV0Wjf9HUkjlH2yonEMv', 'lead-mehak-mittal-01', 'At-Risk', 10, 'Lead has gone cold after client stated they would initiate contact when ready; high risk of loss.', 'Review lead status with management; consider a final, value-driven outreach or re-categorize as \'Lost\' if no response by next follow-up.', '["Client stated they will initiate contact when ready","No payment received after 33 days","Client is exploring options with spouse","Multiple missed follow-ups (CNC)"]', 'This lead is At-Risk. The client (via husband) has explicitly stated they will initiate contact when ready, which often indicates a loss of immediate interest or a decision to go with another option. There have been multiple missed follow-ups (CNC) and the client is still discussing the marriage petition with his wife, indicating indecision or lack of urgency. No payment has been received after 33 days. The next follow-up is distant (06/15/2026), further reducing urgency. The score is low due to these significant risk factors.', '2026-06-07 12:03:45.000', '2026-06-07 12:03:45.000');
INSERT INTO `ai_lead_analysis` (`id`, `leadId`, `tier`, `score`, `headline`, `nextAction`, `riskFlags`, `reasoning`, `analyzedAt`, `createdAt`) VALUES ('OKeb_Ey89narL_NXnb7ct', '1pMi-iVTvhUVoBr7BsrYQ', 'Warm', 10, 'Sahil Kalyan: New DA Lead, Active Follow-up, but Unresponsive. Needs immediate attention to prevent cooling.', 'Attempt immediate contact (call/text) today, 2026-06-08, as per the last note. If no response, consider a different communication channel or a more urgent message. Update CRM with outcome.', '["Unresponsive to calls/texts","No payment received","Next follow-up date is today (2026-06-08), requiring immediate action"]', 'Sahil Kalyan is a new lead (3 days) with a high quote ($9000), indicating potential value. The team has been diligent with follow-ups (2 completed), showing engagement. However, the client has been unresponsive to calls and texts on both June 4th and 5th. The next follow-up is scheduled for today, June 8th, which is critical. While the lead is still \'Warm\' due to recent activity and high potential, lack of response is a significant concern. Immediate and effective follow-up today is crucial to prevent the lead from becoming \'Cold\' or \'At-Risk\'.', '2026-06-07 12:01:22.000', '2026-06-07 12:01:22.000');
INSERT INTO `ai_lead_analysis` (`id`, `leadId`, `tier`, `score`, `headline`, `nextAction`, `riskFlags`, `reasoning`, `analyzedAt`, `createdAt`) VALUES ('p_Y2BwSj10lFog3FGp31g', 'Z4BVicKvWcJjh1fe3J0Yp', 'Warm', 10, 'SIJS Lead engaged, but no quote and minor wants direct attorney consult.', 'Follow up on Monday as planned. Prepare for potential attorney consultation request and clarify fee structure.', '["No quote provided yet","Minor requesting direct attorney consultation (potential for miscommunication or expectation mismatch)","Client has been difficult to reach previously"]', 'The client and minor were successfully contacted on 06/05/2026, and the process was explained. This indicates continued engagement and interest, moving the lead from \'Cold\' after initial CNCs to \'Warm\'. However, no quote has been provided, which is a critical next step. The minor\'s request for a direct attorney consultation, while addressed, could be a point of friction if not managed carefully. Previous CNCs also suggest some difficulty in reaching the client. The next follow-up is planned for Monday, which is a positive sign of continued effort.', '2026-06-05 22:22:12.000', '2026-06-05 22:22:12.000');
INSERT INTO `ai_lead_analysis` (`id`, `leadId`, `tier`, `score`, `headline`, `nextAction`, `riskFlags`, `reasoning`, `analyzedAt`, `createdAt`) VALUES ('pSAN6Py6kwSWRtILBx0HH', 'qMG_lNSUr93-AFLf2PscW', 'At-Risk', 10, 'AOS lead unresponsive after multiple follow-ups; high risk of disengagement.', 'Attempt final contact via alternative method (e.g., email/text if available), or close lead if no response by next scheduled follow-up.', '["Unresponsive to multiple follow-ups","No payment received after 54 days","Repeated \'Client Not Connected\' status","Long period since initial quote without engagement"]', 'This lead is classified as \'At-Risk\' due to a consistent pattern of unresponsiveness across multiple follow-up attempts (four \'Client Not Connected\' instances). Despite being in the follow-up stage for 54 days and having a quote provided, no payment has been received, indicating a lack of commitment or engagement. The repeated failure to connect suggests either disinterest, incorrect contact information, or a change in circumstances. Without a successful connection, the likelihood of converting this lead is rapidly diminishing.', '2026-06-07 12:02:07.000', '2026-06-07 12:02:07.000');
INSERT INTO `ai_lead_analysis` (`id`, `leadId`, `tier`, `score`, `headline`, `nextAction`, `riskFlags`, `reasoning`, `analyzedAt`, `createdAt`) VALUES ('QMFQfkKty2dwtyVZOgifU', 'In_sDaCmPLhgFO5civLYD', 'At-Risk', 10, 'Vasu (Green Card) - Client expressed intent to initiate contact when ready, follow-up scheduled for 2026-06-15.', 'Follow up on 2026-06-15 as per client\'s request. Prepare to offer value-add content or gentle reminder.', '["Lead in follow-up for 33 days without payment","Client stated they will initiate contact when ready, indicating potential disengagement","No quote provided yet, suggesting early stage or lack of commitment"]', 'Vasu is categorized as \'At-Risk\' due to the extended follow-up period (33 days), the client\'s explicit statement to initiate contact when ready, and the absence of a quoted fee or payment. While a next follow-up is scheduled for 2026-06-15, the client\'s communication suggests a passive stance. The score of 30 reflects low engagement and high risk of attrition without further action. The lack of a quote is also a concern, indicating the sales process hasn\'t fully progressed.', '2026-06-07 12:02:29.000', '2026-06-07 12:02:29.000');
INSERT INTO `ai_lead_analysis` (`id`, `leadId`, `tier`, `score`, `headline`, `nextAction`, `riskFlags`, `reasoning`, `analyzedAt`, `createdAt`) VALUES ('QqVakySmBaUxS6mFCMJxZ', 'xaWqfnS6ZBTRCnChX0mBj', 'At-Risk', 10, 'Lead unresponsive after multiple follow-ups; repeatedly asks for free advice instead of booking consultation.', 'Attempt one final follow-up call with a clear offer for consultation, then archive if no response.', '["Unresponsive to follow-ups","Repeatedly seeking free advice/scenarios","Hesitant to commit to consultation fee","Long lead time (12 days) without commitment"]', 'This lead is categorized as \'At-Risk\' due to a pattern of unresponsiveness and a reluctance to commit to a paid consultation despite multiple follow-ups. The client has repeatedly asked for different case scenarios, indicating a desire for free advice rather than engaging for services. After 12 days and 4 completed follow-ups, including instances where the client picked up but didn\'t speak or didn\'t answer, the engagement level is very low. The quoted amount is $0.00 and no payment has been made. The next follow-up is scheduled far in the future (2026-06-08), which is not ideal for an active lead. While initial details were given, the client\'s subsequent behavior suggests a low likelihood of conversion without a significant change in approach or client commitment.', '2026-06-07 12:03:09.000', '2026-06-07 12:03:09.000');
INSERT INTO `ai_lead_analysis` (`id`, `leadId`, `tier`, `score`, `headline`, `nextAction`, `riskFlags`, `reasoning`, `analyzedAt`, `createdAt`) VALUES ('qwUiflRVfcBtUIgPdzlN6', 'h0dzs2vub66X8cxAVO54h', 'Warm', 10, 'Rajninder Kaur: Consultation paid, but no follow-ups completed. Needs immediate attention.', 'Confirm consultation details and send pre-consultation materials. Schedule internal review for post-consultation follow-up strategy.', '["No completed follow-ups despite payment","Next follow-up date is far in the future (potentially an error or oversight)"]', 'Rajninder Kaur has paid for a consultation, indicating strong initial interest and commitment. This places her in the \'Warm\' tier. However, zero completed follow-ups and a distant \'Next follow-up\' date (2026-06-08) are significant red flags. The distant follow-up date is highly unusual and suggests a data entry error or a lack of immediate engagement planning, which could lead to client disengagement. Prompt action is needed to ensure the consultation proceeds smoothly and to establish a proper follow-up cadence.', '2026-06-07 12:00:33.000', '2026-06-07 12:00:33.000');
INSERT INTO `ai_lead_analysis` (`id`, `leadId`, `tier`, `score`, `headline`, `nextAction`, `riskFlags`, `reasoning`, `analyzedAt`, `createdAt`) VALUES ('teqdMQheMTfZKIoYXaQUx', 'RsD9_-8N_ccc2mGAZOXJx', 'Warm', 10, 'Milan Singh: Awaiting payment next week, confirmed follow-up.', 'Follow up with Milan Singh on 2026-06-08 as planned to confirm payment receipt.', '["No payment received after 11 days","Client has not yet committed to proceeding despite follow-ups"]', 'Milan Singh is in the \'Follow-Up\' stage, 11 days post-quote, with no payment received. However, the client has communicated a clear reason for delay (waiting for paycheck) and a specific timeline (\'next week\'), with a confirmed next follow-up date. This indicates continued engagement and a high likelihood of conversion soon, placing him in the \'Warm\' tier. The score reflects the positive communication but also the outstanding payment and lack of formal commitment.', '2026-06-07 12:03:02.000', '2026-06-07 12:03:02.000');
INSERT INTO `ai_lead_analysis` (`id`, `leadId`, `tier`, `score`, `headline`, `nextAction`, `riskFlags`, `reasoning`, `analyzedAt`, `createdAt`) VALUES ('UTdO1TO7ldWSgPc2XrcjW', 'hNM5AoXqCkBX_n3DhHVMH', 'Warm', 10, 'U-Visa lead with pending asylum case, awaiting final hearing outcome.', 'Follow up on 2026-06-09 as planned, specifically inquiring about the outcome of the asylum final hearing and its potential impact on the U-Visa application.', '["No payment received","Dependent on outcome of another complex legal case (asylum)","Potential for delayed decision making due to asylum case"]', 'This lead is categorized as \'Warm\' because there is active engagement (client responded to follow-up, next follow-up scheduled) and a clear next step. However, the lack of payment and the dependency on a pending asylum case with a final hearing next week introduce significant uncertainty and risk. The outcome of the asylum case will heavily influence their ability and willingness to proceed with the U-Visa. The score reflects the engagement balanced with the financial and legal dependencies.', '2026-06-07 12:02:18.000', '2026-06-07 12:02:18.000');
INSERT INTO `ai_lead_analysis` (`id`, `leadId`, `tier`, `score`, `headline`, `nextAction`, `riskFlags`, `reasoning`, `analyzedAt`, `createdAt`) VALUES ('wHpk-iUBSGciT8CQcmHGg', 'h6VWli-cup9mEdSsxKCZS', 'Warm', 10, 'Client committed to starting \'next week\', follow-up scheduled.', 'Follow up with Vishal Kumar on 2026-06-08 as planned.', '["No payment received","No initial quote provided"]', 'The client, Vishal Kumar, has verbally committed to starting his case \'next week\' and a follow-up is already scheduled for 2026-06-08. This indicates a strong interest, moving him from Cold to Warm. However, no quote has been provided yet, and no payment has been received, which are significant risk factors. The \'DA\' case type is typically a high-value case, making this lead important to nurture. The score reflects his verbal commitment but also the lack of financial engagement.', '2026-06-07 12:02:47.000', '2026-06-07 12:02:47.000');
INSERT INTO `ai_lead_analysis` (`id`, `leadId`, `tier`, `score`, `headline`, `nextAction`, `riskFlags`, `reasoning`, `analyzedAt`, `createdAt`) VALUES ('WYyhbUhQIOaYnZG73UuZF', 'YYMxuSI3XIJjIxApl1MRd', 'At-Risk', 10, 'Critical SIJS Lead: No Quote, No Follow-up, High Risk of Loss', 'Immediately contact Tarunjot Singh to understand current situation, offer a pro-bono or reduced fee consultation, and provide an initial quote. Prioritize understanding barriers to engagement.', '["No quote provided","No follow-ups completed","Extended time since last action (18 days)","Vulnerable case type (SIJS) with no financial commitment"]', 'This lead is classified as \'At-Risk\' due to several critical factors. The SIJS case type typically involves vulnerable individuals, making the lack of a quote and completed follow-ups particularly concerning. 18 days have passed without engagement, indicating a high probability of disinterest or finding alternative counsel. The absence of a quote suggests a fundamental breakdown in the initial consultation or sales process, leaving the lead with no clear path forward. Without immediate intervention, this lead is highly likely to be lost.', '2026-06-07 12:03:21.000', '2026-06-07 12:03:21.000');
INSERT INTO `ai_lead_analysis` (`id`, `leadId`, `tier`, `score`, `headline`, `nextAction`, `riskFlags`, `reasoning`, `analyzedAt`, `createdAt`) VALUES ('xJ890AFnwSV6KErwpHRRg', 'fSMz4BnpXXvwoQWk_GcqR', 'Warm', 10, 'Manpreet Singh: Waiting for funds, committed to starting next week.', 'Follow up on Monday, 2026-06-08, as agreed, to confirm payment and case initiation.', '[]', 'Manpreet Singh is in the \'Follow-Up\' stage for a DA case. He has been quoted $10,000 but has not yet paid. The key note indicates he will receive his paycheck next week and intends to start the case then, with a follow-up scheduled for Monday (2026-06-08). This shows a clear commitment and a defined timeline for moving forward, making him a warm lead. There are no immediate red flags, but the lack of payment means he\'s not yet hot. The next action is clearly defined by the client\'s own statement.', '2026-06-07 12:02:02.000', '2026-06-07 12:02:02.000');
INSERT INTO `ai_lead_analysis` (`id`, `leadId`, `tier`, `score`, `headline`, `nextAction`, `riskFlags`, `reasoning`, `analyzedAt`, `createdAt`) VALUES ('YZpuTVGnSD5riekaiItCV', 'r6Fhbms_Mwn5mwxmlS_KE', 'At-Risk', 10, 'Lead unresponsive after multiple follow-ups; high risk of disengagement.', 'Attempt final contact via phone and email. If no response, move to \'Cold\' or \'Closed Lost\'.', '["Unresponsive to multiple follow-ups","No quote provided","No engagement with family discussion","Long period of unresponsiveness (10 days with 4+ attempts)"]', 'Sujeet Singh is a new lead for a Mother Green Card case, 10 days old, with no quote or payment. Despite 4 completed follow-ups and multiple attempts to contact him via text and phone, he has been consistently unresponsive to queries about discussing the case with his family. The last note indicates an attempt to understand why they might not want to proceed, which is a strong indicator of disengagement. The lead is at high risk of being lost due to lack of communication and commitment.', '2026-06-07 12:02:57.000', '2026-06-07 12:02:57.000');
INSERT INTO `ai_lead_analysis` (`id`, `leadId`, `tier`, `score`, `headline`, `nextAction`, `riskFlags`, `reasoning`, `analyzedAt`, `createdAt`) VALUES ('ZeIPs-L-dPZYpBVg2k2B5', 'MW959ff-YUx7IMK3bGHBm', 'At-Risk', 10, 'Jaskaran: Unresponsive New Lead - Multiple CNCs, No Engagement', 'Attempt final contact via different channel (email/text), then consider archiving if no response by next scheduled follow-up.', '["No client engagement","Multiple \'Client Not Contacted\' (CNC) entries","No quote provided","Lead unresponsive to initial outreach"]', 'Jaskaran is a new lead (5 days old) who has not been successfully contacted despite 3 completed follow-ups. All attempts resulted in \'Client Not Contacted\' (CNC) messages being dropped. No quote has been provided, indicating a complete lack of engagement. This lead is at high risk of becoming cold if engagement is not established immediately.', '2026-06-07 12:01:51.000', '2026-06-07 12:01:51.000');
INSERT INTO `daily_briefings` (`id`, `briefingDate`, `content`, `tierSummary`, `topActions`, `memberAssignments`, `escalations`, `createdAt`, `unassignedLeads`) VALUES ('5yKGMRsMycMP_MXeKT9Yn', '2026-06-04', 'Good morning, team. Today\'s pipeline health shows 2 Hot, 10 Warm, 9 At-Risk, and 6 Cold leads, with 9 Retained cases. Our immediate focus must be on converting Hot and Warm leads and mitigating risks with At-Risk leads.\n\nToday, we have several critical follow-ups. Sachin needs to handle the initial consultation for Tajinder Singh (Hot DA lead) and also follow up with Vitek Vitek (Warm SIJS) and Navneet (Warm AOS). Josh will focus on Sahil Kalyan (Warm DA) for a direct contact attempt and follow up with Soni (Warm AO) regarding a referral. Milan will address the at-risk lead Balwant Singh (DA) with a final contact attempt.\n\nSeveral leads are at high risk of disengagement. Jaskaran (DA), Abdul Adam (Green Card), Sujeet Singh (Green Card), Balwant Singh (DA), Akashdeep Singh (DA), and Tarunjot Singh (SIJS) all require immediate, decisive action to prevent them from moving to \'Cold\' or being archived. We need to exhaust all contact methods today for these leads.\n\nFor today, the team\'s priority is to execute all scheduled follow-ups, especially for Hot and Warm leads. Additionally, we must aggressively pursue the At-Risk leads to either re-engage them or make a clear decision on their status. Khushi should support with any necessary data gathering or scheduling to facilitate these actions.', '{"Hot":2,"Warm":10,"At-Risk":9,"Cold":6,"Unanalyzed":9}', '[{"leadName":"Tajinder Singh","tier":"Hot","action":"Initial consultation call and send introductory email with firm brochure and next steps for DA case."},{"leadName":"Sahil Kalyan","tier":"Warm","action":"Attempt direct contact via phone call on 2026-06-05. If no answer, leave a voicemail and send a follow-up email summarizing the quote and next steps."},{"leadName":"Soni","tier":"Warm","action":"Follow up with Gursahib Singh tomorrow (2026-06-05) as planned to get an update on his friend\'s decision and try to obtain the friend\'s contact information."},{"leadName":"Vitek Vitek (Guardian)","tier":"Warm","action":"Attempt immediate phone contact with Vitek Vitek. If unsuccessful, send a personalized email summarizing previous attempts and offering specific times for a call today or tomorrow. Update the next follow-up date accordingly."},{"leadName":"Navneet","tier":"Warm","action":"Follow up with Navneet on 06/05/2026 regarding consultation payment."},{"leadName":"Mehak Mittal (Vasu)","tier":"Warm","action":"Follow up on 2026-06-05 as planned. Attempt to reach client directly to confirm decision on marriage petition and address recent communication issues."}]', '[{"memberName":"Sachin","tasks":["Conduct initial consultation for Tajinder Singh (Hot DA lead).","Attempt immediate phone contact with Vitek Vitek (Warm SIJS). If unsuccessful, send personalized email.","Follow up with Navneet (Warm AOS) regarding consultation payment."]},{"memberName":"Josh","tasks":["Attempt direct contact via phone for Sahil Kalyan (Warm DA) on 2026-06-05. Send follow-up email if no answer.","Follow up with Gursahib Singh for Soni (Warm AO) to get update on friend\'s decision and contact info."]},{"memberName":"Milan Singh","tasks":["Attempt final contact for Balwant Singh (At-Risk DA) via different channel with clear call to action.","Attempt final contact for Jaskaran (At-Risk DA) via alternative method.","Conduct immediate outreach to Abdul Adam (At-Risk Green Card) to determine interest and provide quote.","Attempt different communication channel or direct consultation for Sujeet Singh (At-Risk Green Card).","Attempt final contact for Akashdeep Singh (At-Risk DA) via alternative methods.","Immediately attempt to contact Tarunjot Singh (At-Risk SIJS) via all available channels."]},{"memberName":"Khushi Arora","tasks":["Support team with scheduling and data gathering as needed for today\'s high-priority actions."]}]', '[{"leadName":"Jaskaran","reason":"At-Risk: Attempt final contact today via alternative method or consider archiving."},{"leadName":"Abdul Adam","reason":"At-Risk: Immediate outreach to determine interest and provide initial quote. If no response, archive."},{"leadName":"Sujeet Singh (Mother Green card)","reason":"At-Risk: Attempt a different communication channel or offer a direct consultation to re-engage."},{"leadName":"Balwant singh","reason":"At-Risk: Attempt final contact via different channel with clear call to action for consultation or closure. If no response, move to \'Cold\' or \'Closed\' status."},{"leadName":"Akashdeep Singh","reason":"At-Risk: Attempt final contact via alternative methods, leave clear message about next steps, then archive if no response."},{"leadName":"Tarunjot Singh","reason":"At-Risk: Immediately attempt to contact via all available channels. If no response, consider archiving or re-engaging with a different strategy."}]', '2026-06-05 08:45:29.000', NULL);
INSERT INTO `daily_briefings` (`id`, `briefingDate`, `content`, `tierSummary`, `topActions`, `memberAssignments`, `escalations`, `createdAt`, `unassignedLeads`) VALUES ('PthSZtFQO05PWYR6F-f_L', '2026-06-06', 'Today\'s pipeline health requires immediate attention to several at-risk and overdue leads to prevent loss. Khushi has one overdue follow-up that needs to be actioned immediately, and several high-priority at-risk leads require proactive engagement today. The focus for the team today is on urgent follow-ups and ensuring all unassigned leads are properly owned.\n\nKhushi\'s immediate priorities include following up with Sujeet Singh (Mother Green card) who is overdue, and proactively engaging with Tarunjot Singh (SIJS) and Abdul Adam (Green Card) to prevent them from going cold. These leads represent critical opportunities that need focused effort today.\n\nSachin has no new escalations today, allowing him to focus on ongoing strategic initiatives. There are no other team members with explicit lead assignments requiring action today.\n\nCrucially, a significant number of leads are currently unassigned and require immediate assignment to Khushi to ensure they enter the proper workflow and receive timely follow-up. This is a critical administrative task for today to maintain pipeline integrity.', '{"Hot":2,"Warm":10,"At-Risk":11,"Cold":5,"Unanalyzed":9}', '[{"leadName":"Sujeet Singh (Mother Green card)","tier":"Warm","action":"Immediately attempt a direct phone call to discuss family decision and next steps for the Green Card process. If no answer, send a text/email summarizing the call attempt and reiterating the offer to discuss."},{"leadName":"Tarunjot Singh","tier":"At-Risk","action":"Immediately attempt to contact via all available channels (phone, email, text) to understand current situation and offer initial consultation. Prioritize due to SIJS nature."},{"leadName":"Abdul Adam","tier":"At-Risk","action":"Immediately attempt to contact via phone and email. 